<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { opcApi } from '@/api/opc'
type Rule={id:string;category:string;item_key:string;label:string;unit:string;unit_price:number;currency:string;version:number;is_active:boolean}
const useMock=import.meta.env.VITE_USE_MOCK==='true';const dialog=ref(false)
const labels:Record<string,string>={low_carbon_steel:'低碳钢丝',galvanized_steel:'镀锌钢丝',stainless_304:'不锈钢304',stainless_316:'不锈钢316',welded_mesh:'焊接网加工',fence_mesh:'护栏网加工',hexagonal_mesh:'六角网加工',screen_mesh:'工业筛网加工',expanded_mesh:'钢板网加工',none:'无处理',electro_galvanized:'电镀锌',hot_dip_galvanized:'热镀锌',pvc_coated:'浸塑',powder_coated:'喷塑',bulk:'散装',pallet:'托盘',export:'出口包装'}
const rules=ref<Rule[]>([
  {id:'p1',category:'material',item_key:'low_carbon_steel',label:'低碳钢丝',unit:'kg',unit_price:4.6,currency:'CNY',version:1,is_active:true},
  {id:'p2',category:'material',item_key:'galvanized_steel',label:'镀锌钢丝',unit:'kg',unit_price:5.4,currency:'CNY',version:1,is_active:true},
  {id:'p3',category:'process',item_key:'welded_mesh',label:'焊接网加工',unit:'m²',unit_price:4.2,currency:'CNY',version:1,is_active:true},
  {id:'p4',category:'surface',item_key:'hot_dip_galvanized',label:'热镀锌',unit:'kg',unit_price:1.15,currency:'CNY',version:1,is_active:true},
  {id:'p5',category:'packaging',item_key:'export',label:'出口包装',unit:'m²',unit_price:1.2,currency:'CNY',version:1,is_active:true},
])
const form=reactive({category:'material',item_key:'',unit:'kg',unit_price:0,currency:'CNY'})
onMounted(async()=>{if(useMock)return;const{data}=await opcApi.listPrices();if(data.length)rules.value=data.map((x:any)=>({...x,label:labels[x.item_key]||x.item_key}))})
function openCreate(){Object.assign(form,{category:'material',item_key:'',unit:'kg',unit_price:0,currency:'CNY'});dialog.value=true}
async function save(){if(!form.item_key||form.unit_price<0)return ElMessage.warning('请填写规则标识和有效单价');const id=useMock?`p-${Date.now()}`:(await opcApi.createPrice({...form,is_active:1,extra:{}})).data.id;const previous=rules.value.find(x=>x.category===form.category&&x.item_key===form.item_key&&x.is_active);if(previous)previous.is_active=false;rules.value.unshift({id,...form,label:labels[form.item_key]||form.item_key,version:(previous?.version||0)+1,is_active:true});dialog.value=false;ElMessage.success('新价格版本已发布')}
async function deactivate(x:Rule){await ElMessageBox.confirm(`停用 ${x.label} v${x.version}？`,'停用价格',{type:'warning'});if(!useMock)await opcApi.deactivatePrice(x.id);x.is_active=false;ElMessage.success('价格规则已停用')}
defineExpose({openCreate})
</script>
<template><div><div class="notice"><el-icon><InfoFilled/></el-icon><span>报价引擎只读取“生效中”的最新价格版本；历史报价保留原计算结果。</span></div><section class="card"><header><h3>价格规则与版本</h3><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>发布价格</el-button></header><div class="row head"><span>分类</span><span>项目</span><span>标识</span><span>单价</span><span>单位</span><span>版本</span><span>状态</span><span>操作</span></div><div v-for="x in rules" :key="x.id" class="row"><span>{{ x.category }}</span><b>{{ x.label }}</b><code>{{ x.item_key }}</code><strong>{{ x.currency }} {{ x.unit_price }}</strong><span>/ {{ x.unit }}</span><span>v{{ x.version }}</span><em :class="{active:x.is_active}">{{ x.is_active?'生效中':'已停用' }}</em><button :disabled="!x.is_active" @click="deactivate(x)">停用</button></div></section><el-dialog v-model="dialog" title="发布新价格版本" width="560px"><el-form label-position="top"><div class="form-grid"><el-form-item label="价格分类"><el-select v-model="form.category"><el-option label="材料" value="material"/><el-option label="加工" value="process"/><el-option label="表面处理" value="surface"/><el-option label="包装" value="packaging"/></el-select></el-form-item><el-form-item label="规则标识"><el-input v-model="form.item_key" placeholder="如 low_carbon_steel"/></el-form-item><el-form-item label="单价"><el-input-number v-model="form.unit_price" :min="0" :precision="2"/></el-form-item><el-form-item label="单位"><el-input v-model="form.unit"/></el-form-item><el-form-item label="币种"><el-select v-model="form.currency"><el-option label="CNY" value="CNY"/><el-option label="USD" value="USD"/><el-option label="EUR" value="EUR"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">发布版本</el-button></template></el-dialog></div></template>
<style scoped>.notice{display:flex;gap:8px;align-items:center;background:#eaf3ff;color:#416b9d;border:1px solid #d8e7f9;border-radius:9px;padding:11px 14px;font-size:10px;margin-bottom:14px}.card{background:#fff;border:1px solid #e2eaf2;border-radius:12px;padding:18px;box-shadow:0 5px 18px rgba(23,47,79,.045)}.card header{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.card h3{margin:0;font-size:15px}.row{display:grid;grid-template-columns:.65fr 1fr 1.3fr .8fr .5fr .4fr .6fr .4fr;gap:10px;align-items:center;min-height:52px;border-top:1px solid #edf1f5;color:#5e7085;font-size:9px}.row.head{min-height:34px;border:0;color:#95a0ae}.row code{background:#f2f5f8;padding:4px 6px;border-radius:4px;font-size:8px}.row em{font-style:normal;width:fit-content;padding:4px 7px;border-radius:10px;background:#eef2f6}.row em.active{background:#e5f7ef;color:#158161}.row button{border:0;background:#fff0ef;color:#d25a4d;border-radius:4px;padding:5px;font-size:8px;cursor:pointer}.row button:disabled{opacity:.35}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .el-select,.form-grid .el-input-number{width:100%}@media(max-width:800px){.card{overflow:auto}.row{min-width:750px}.form-grid{grid-template-columns:1fr}}</style>
